    s.gold += gold;
    this.pushLog(`【弃印】放下${(NDX.SEAL_TIER_LABEL && NDX.SEAL_TIER_LABEL[sl.tier]) || sl.tier}「${sl.name}」（${sl.dao}道）——香火化金 +${gold}（现 ${s.gold}）`);
